parameters.jsCode:
// Arbeitsliste als HTML-Seite. Werte werden escaped, weil Mailtexte von außen kommen.
// Kein CSS-Framework und keine Schrift von fremden Servern: Die Seite zeigt vertrauliche Preise und soll auch ohne Internet laufen.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const reviews = $('Offene Reviews laden').all().map((i) => i.json).filter((r) => r.id);
const aufgaben = $('Offene Aufgaben laden').all().map((i) => i.json).filter((a) => a.id);
const k = $('Kennzahlen und Audit laden').first().json;
const e = k.einstellungen ?? {};

// Anonyme Ansicht für Screenshots (?anonym=1): Der Server ersetzt die Daten, bevor die Seite den Browser erreicht.
// Ein Skript, das erst im Browser maskiert, ließe die echten Werte im Quelltext stehen und übersieht leicht Freitext.
// Deshalb fallen Mailtexte, Betreffs, Zusammenfassungen und Antwortentwürfe hier ganz weg.
const anonym = String($('Webhook Arbeitsliste').first().json.query?.anonym ?? '') === '1';
const pseudonym = (bilde) => {
  const vergeben = new Map();
  return (wert) => {
    if (wert === null || wert === undefined || wert === '') return '–';
    if (!anonym) return esc(wert);
    if (!vergeben.has(wert)) vergeben.set(wert, bilde(vergeben.size));
    return `<span class="maske">${vergeben.get(wert)}</span>`;
  };
};
const lieferant = pseudonym((i) => `[LIEFERANT_${String.fromCharCode(65 + (i % 26))}${i >= 26 ? Math.floor(i / 26) : ''}]`);
const nummer = pseudonym((i) => `ID-${String(i + 1).padStart(3, '0')}`);
const person = pseudonym((i) => `[MITARBEITER_${i + 1}]`);
const AUSGEBLENDET = '<span class="maske">[ausgeblendet]</span>';

// Zahlen immer in Monospace. Beträge sind im Screenshot-Modus maskiert, Prozentwerte und Daten bleiben sichtbar.
const de = (n, stellen = 2) => Number(n).toLocaleString('de-DE', { minimumFractionDigits: stellen, maximumFractionDigits: stellen });
const zahl = (n) => `<span class="num">${Number(n).toLocaleString('de-DE', { maximumFractionDigits: 4 })}</span>`;
const betrag = (n, waehrung = 'EUR') => (anonym ? '<span class="maske num">***,** €</span>'
  : `<span class="num">${de(n)}&nbsp;${waehrung === 'EUR' ? '€' : esc(waehrung)}</span>`);
const prozent = (n) => `<span class="num">${Number(n) > 0 ? '+' : ''}${Number(n).toLocaleString('de-DE', { maximumFractionDigits: 1 })}&nbsp;%</span>`;
const datum = (d) => (d ? `<span class="num">${(typeof d === 'string' ? d : new Date(d).toISOString()).slice(0, 10).split('-').reverse().join('.')}</span>` : '–');

// Micro-Icons als Inline-SVG, Farbe kommt über currentColor aus dem Badge
const ICON = {
  punkt: '<svg viewBox="0 0 8 8" class="i"><circle cx="4" cy="4" r="3" fill="currentColor"/></svg>',
  haken: '<svg viewBox="0 0 16 16" class="i"><path d="M3.5 8.5l3 3 6-7" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  warnung: '<svg viewBox="0 0 16 16" class="i"><path d="M8 2.2L14.3 13H1.7z" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/><path d="M8 6.5v3" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/><circle cx="8" cy="11.3" r=".8" fill="currentColor"/></svg>',
  kreis: '<svg viewBox="0 0 16 16" class="i"><circle cx="8" cy="8" r="5.5" fill="none" stroke="currentColor" stroke-width="1.4"/></svg>',
  info: '<svg viewBox="0 0 16 16" class="i"><circle cx="8" cy="8" r="6.2" fill="none" stroke="currentColor" stroke-width="1.2"/><path d="M8 7.2v4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/><circle cx="8" cy="5" r=".85" fill="currentColor"/></svg>',
  schloss: '<svg viewBox="0 0 16 16" class="i"><rect x="3" y="7" width="10" height="7" rx="1.5" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M5.5 7V5a2.5 2.5 0 015 0v2" fill="none" stroke="currentColor" stroke-width="1.4"/></svg>',
  offen: '<svg viewBox="0 0 16 16" class="i"><rect x="3" y="7" width="10" height="7" rx="1.5" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M5.5 7V5a2.5 2.5 0 014.9-.6" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>',
};
const badge = (ton, text, puls = false) => `<span class="badge ${ton}">${puls ? '<span class="puls"></span>' : ICON[{ krit: 'warnung', warn: 'kreis', ok: 'haken', neutral: 'punkt' }[ton]]}${esc(text)}</span>`;
// Regelbegründung als Tooltip: zeigt, welche Regel mit welchen Werten entschieden hat
const regel = (text) => (text ? `<span class="tip" tabindex="0" aria-label="${esc(text)}" data-tip="${esc(text)}">${ICON.info}</span>` : '');
const befund = (ton, html, regeltext) => `<li class="befund ${ton}">${ICON[{ krit: 'warnung', warn: 'kreis', ok: 'haken', neutral: 'punkt' }[ton]]}<span>${html}</span>${regel(regeltext)}</li>`;
// Geschütztes Leerzeichen, damit Zahl und Einheit nicht umbrechen (auch in Tooltips, deshalb kein &nbsp;)
const pz = (n) => `${Number(n).toLocaleString('de-DE', { maximumFractionDigits: 1 })} %`;
const eur = (n) => `${Number(n).toLocaleString('de-DE')} €`;

// Befunde je Aufgabe: was das System festgestellt hat und nach welcher Regel
const TERMIN = {
  termin_unsicher: (a) => [`Termin unsicher, gewünscht ${datum(a.gewuenscht)}`, 'Lieferant nennt den Termin nur voraussichtlich oder ohne Gewähr'],
  termin_fehlt: (a) => [`Kein Termin bestätigt, gewünscht ${datum(a.gewuenscht)}`, 'Die AB enthält keinen konkreten Liefertermin'],
  termin_spaeter: (a) => [`Termin ${datum(a.gewuenscht)} → ${datum(a.bestaetigt)}`, 'Bestätigter Termin liegt nach dem Wunschtermin der Bestellung'],
};
const PRUEFGRUND = {
  liefertreue_unter_schwelle: (ab) => [`Liefertreue <span class="num">${esc(ab.liefertreue)}&nbsp;%</span> unter Schwelle`,
    `System-Flag: Liefertreue ${ab.liefertreue} % < Schwellenwert ${ab.schwelle} % (${ab.abc_xyz}-Artikel)`],
  blindbestaetigung_verdacht: (ab) => [`AB nach <span class="num">${esc(ab.bearbeitungszeit_minuten)}</span> Minuten: Blindbestätigung?`,
    `System-Flag: Bearbeitungszeit ${ab.bearbeitungszeit_minuten} min < ${e.blindbestaetigung_minuten ?? 30} min nach Bestellversand`],
  neuer_lieferant: () => ['Neuer Lieferant: Kontakt aufnehmen und Termin absichern', 'System-Flag: Lieferant ohne Liefertreue-Historie'],
  absender_domain_abweichend: () => ['Absender-Domain passt nicht zum Lieferanten', 'System-Flag: Domain des Absenders weicht von der Domain in den Stammdaten ab'],
};
const preisBefunde = (d) => {
  const b = [];
  if (d.angabe_lieferant_prozent != null) {
    b.push(befund('warn', `Lieferant nennt ${prozent(d.angabe_lieferant_prozent)}, gerechnet ${prozent(d.prozent)}`,
      'System-Flag: Angabe des Lieferanten weicht um mehr als 0,5 Prozentpunkte von Bestell- und AB-Preis ab'));
  }
  if ((d.alter_preis_gilt ?? []).length) {
    b.push(befund('warn', `Zum alten Preis bestätigt: ${d.alter_preis_gilt.map(nummer).join(', ')}. Alter Preis gilt, Rechnung prüfen`,
      'System-Flag: Bestätigung des Lieferanten liegt vor dem Eingang der Mitteilung, der vereinbarte Preis gilt'));
  }
  if (d.jahresbedarf_fehlt === true || (Array.isArray(d.jahresbedarf_fehlt) && d.jahresbedarf_fehlt.length)) {
    b.push(befund('warn', `Jahresbedarf fehlt${Array.isArray(d.jahresbedarf_fehlt) ? ` für ${esc(d.jahresbedarf_fehlt.join(', '))}` : ''}`,
      'Ohne Jahresbedarf lässt sich der Full-Year-Effekt nicht berechnen. Er wird nicht als 0 € gezählt.'));
  }
  const letzte = d.letzte_aenderung ?? d.letzte_erhoehung;
  if (letzte) b.push(befund('neutral', `Letzte Erhöhung ${datum(letzte.gueltig_ab)}: ${prozent(letzte.prozent)}`, 'Quelle: Tabelle preis_historie'));
  if (d.prozent_12_monate != null) {
    b.push(befund(d.prozent_12_monate > Number(e.preis_toleranz_dispo_prozent ?? 5) ? 'warn' : 'neutral',
      `Zwölf Monate zusammen: ${prozent(d.prozent_12_monate)}`, 'Neuer Preis gegen den Preis, der vor zwölf Monaten galt'));
  }
  return b;
};
const befunde = (a) => {
  const d = a.details ?? {};
  const b = [];
  if (a.art === 'eskalation') {
    for (const g of d.eskalation ?? []) {
      if (g === 'jahres_mehrkosten') {
        const grenze = a.team === 'Geschäftsleitung' ? e.eskalation_geschaeftsleitung_euro : e.eskalation_einkaufsleitung_euro;
        b.push(befund('krit', `Jahreswirkung über der Freigabegrenze von <span class="num">${esc(eur(grenze))}</span>`,
          `System-Flag: Full-Year-Effekt ${anonym ? '***' : eur(d.jahres_mehrkosten_eur)} ≥ Schwellenwert ${eur(grenze)}`));
      }
      if (g === 'liefertreue_und_preis') {
        b.push(befund('krit', 'Hohe Erhöhung bei schwacher Liefertreue: Alternativlieferant prüfen',
          `System-Flag: Liefertreue ${pz(d.liefertreue)} < ${pz(e.eskalation_liefertreue_prozent)} und Erhöhung ${pz(d.prozent)} > ${pz(e.eskalation_liefertreue_preis_prozent)}`));
      }
    }
  }
  if (a.art === 'preis_freigeben') {
    b.push(befund('ok', 'Innerhalb der Freigabegrenze der Disposition',
      `Regel: Erhöhung ${pz(d.prozent)} ≤ ${pz(e.preis_toleranz_dispo_prozent)}, Mehrkosten ≤ ${eur(e.preis_toleranz_dispo_euro)} je Bestellung und Jahreswirkung < ${eur(e.eskalation_einkaufsleitung_euro)}`));
  }
  if (a.art === 'preiserhoehung_pruefen') {
    b.push(befund(a.prioritaet === 'hoch' ? 'warn' : 'neutral', a.prioritaet === 'hoch' ? 'Über der Freigabegrenze der Disposition' : 'Unter der Freigabegrenze, Entscheidung beim Einkäufer',
      `Regel: Hohe Priorität ab Erhöhung > ${pz(e.preis_toleranz_dispo_prozent)}, Mehrkosten > ${eur(e.preis_toleranz_dispo_euro)} oder Jahreswirkung ≥ ${eur(e.eskalation_einkaufsleitung_euro)}`));
  }
  if (a.art === 'preis_info' && a.team === 'Strategischer Einkauf') {
    b.push(befund('neutral', 'Info an den strategischen Einkauf', `Regel: Erhöhung ≥ ${pz(e.preis_eskalation_strategie_prozent)}`));
  }
  if (['eskalation', 'preis_freigeben', 'preiserhoehung_pruefen', 'preis_info'].includes(a.art)) b.push(...preisBefunde(d));
  // Merker von Modell und Regel: Technik, QM, Disposition. Nur Vorschlag, eingebunden wird per Knopf.
  const ab = a.abteilungen ?? {};
  const betroffen = ['technik', 'qm', 'dispo'].filter((x) => ab[x]);
  if (betroffen.length && !['technik_freigabe', 'qm_freigabe', 'bestand_pruefen', 'entwurf_senden'].includes(a.art)) {
    const namen = { technik: 'Technik', qm: 'QM', dispo: 'Disposition' };
    const quelle = [ab.modell?.length ? `Modell: ${ab.modell.map((x) => namen[x]).join(', ')}` : null,
      ab.regel?.length ? `Regel: ${ab.regel.join(', ')}` : null].filter(Boolean).join(' · ');
    const werkstoff = ab.werkstoff_alt || ab.werkstoff_neu ? ` (Werkstoff <span class="num">${esc(ab.werkstoff_alt ?? '?')}</span> → <span class="num">${esc(ab.werkstoff_neu ?? '?')}</span>)` : '';
    b.push(befund('krit', `${betroffen.map((x) => namen[x]).join(', ')} erforderlich${werkstoff}`, `System-Flag: ${quelle}. Aufgaben entstehen erst über „Technik & QM einbinden“`));
    if (ab.empfehlung && !anonym) b.push(befund('neutral', `Vorschlag des Modells, ungeprüft: ${esc(ab.empfehlung)}`, 'Freier Text des Sprachmodells, nicht durch Regeln geprüft'));
  }
  if (PREISARTEN.includes(a.art) && gesperrt(a)) {
    b.push(befund('warn', 'Preisfreigabe gesperrt, bis Technik und QM freigegeben haben', 'Regel: Bei Material- oder Werkstoffänderung keine Preisfreigabe ohne Freigabe von Technik und QM (prüft auch der Server)'));
  }
  if (['technik_freigabe', 'qm_freigabe', 'bestand_pruefen'].includes(a.art)) {
    if (d.aenderung) b.push(befund('warn', esc(d.aenderung), 'Aus der Mail des Lieferanten, Werkstoffe per Belegprüfung gegen den Mailtext geprüft'));
    b.push(befund('neutral', {
      technik_freigabe: 'Ist der neue Werkstoff bzw. Nachfolger zulässig? Braucht es eine Zeichnungsänderung?',
      qm_freigabe: 'Erstmusterprüfung, Prüfumfang und Zeugnisse (z. B. 3.1 nach EN 10204) festlegen',
      bestand_pruefen: 'Reichweite des Bestands prüfen, letzte Bestellung im bisherigen Werkstoff nötig?',
    }[a.art], 'Bis zur Freigabe von Technik und QM wird nichts umgestellt'));
    if (d.empfehlung && !anonym) b.push(befund('neutral', `Vorschlag des Modells, ungeprüft: ${esc(d.empfehlung)}`, 'Freier Text des Sprachmodells'));
  }
  if (a.art === 'liefertermin_pruefen') {
    for (const t of d.abweichungen ?? []) { const [text, r] = TERMIN[t.art]?.(t) ?? [esc(t.art), null]; b.push(befund('warn', text, r)); }
  }
  if (a.art === 'ab_klaeren') {
    const ab = a.ab_pruefung ?? {};
    for (const m of d.abweichungen ?? []) {
      if (m.art === 'menge') {
        b.push(befund('warn', `Menge ${zahl(m.bestellt)} → ${zahl(m.bestaetigt)}${m.grund && !anonym ? ` (${esc(m.grund)})` : ''}`, 'Bestätigte Menge weicht von der Bestellung ab'));
        if (m.mehrwert) b.push(befund('neutral', `${m.mehrwert > 0 ? 'Mehrwert' : 'Minderwert'} ${betrag(Math.abs(m.mehrwert), m.waehrung)}`, 'Mengendifferenz × Einzelpreis'));
        if (m.passt_zur_vpe === true) b.push(befund('ok', `Volle Verpackungseinheiten à ${zahl(m.vpe_stamm)}`, `Bestätigte Menge ist ein Vielfaches der VPE ${m.vpe_stamm} aus den Stammdaten`));
        if (m.passt_zur_vpe === false) b.push(befund('warn', `Passt nicht zur VPE ${zahl(m.vpe_stamm)} in den Stammdaten`, `System-Flag: ${m.bestaetigt} ist kein Vielfaches von ${m.vpe_stamm}. Stammdaten oder AB prüfen`));
        if (m.moq_stamm && m.bestellt < m.moq_stamm) b.push(befund('warn', `Bestellung lag unter der Mindestmenge ${zahl(m.moq_stamm)}`, 'Bestellmenge < Mindestbestellmenge laut Stammdaten'));
      } else if (m.art === 'stammdaten_pruefen') {
        b.push(befund('warn', `Stammdaten prüfen${m.hinweis && !anonym ? `: ${esc(m.hinweis)}` : ''}`, 'Lieferant nennt Verpackungseinheit oder Stammdaten als Grund'));
      }
    }
    for (const g of d.pruefgruende ?? []) { const [text, r] = PRUEFGRUND[g]?.(ab) ?? [esc(g), null]; b.push(befund('warn', text, r)); }
  }
  return b;
};

// Kennwerte je Aufgabe als zweispaltiges Datengitter
const gitter = (a) => {
  const d = a.details ?? {};
  const felder = [
    ['Bestellung', a.bestellnummer ? `<span class="num">${nummer(a.bestellnummer)}</span>` : null],
    ['Artikel', a.artikel ? esc(a.artikel) : null],
    ['Zuständig', a.zustaendig ? person(a.zustaendig) : null],
    ['Erhöhung', d.prozent != null ? prozent(d.prozent) + (d.prozent_quelle === 'berechnet' ? ' <span class="leise">berechnet</span>' : '') : null],
    ['Preis', d.art === 'preis' ? `${betrag(d.bestellt, d.waehrung)} → ${betrag(d.bestaetigt, d.waehrung)}` : null],
    ['Mehrkosten', d.mehrkosten != null ? `${betrag(d.mehrkosten, d.waehrung)} <span class="leise">${d.art === 'preis' ? 'diese Bestellung' : `${(d.betroffene_bestellungen ?? []).length} offene Bestellungen`}</span>` : null],
    ['Full-Year-Effekt', d.jahres_mehrkosten_eur != null ? betrag(d.jahres_mehrkosten_eur) : null],
    ['Gültig ab', d.gueltig_ab ? datum(d.gueltig_ab) : null],
    ['Liefertreue', d.liefertreue != null ? `<span class="num">${esc(d.liefertreue)}&nbsp;%</span>` : null],
    ['Termin', a.art === 'liefertermin_pruefen' && d.bestaetigt ? `${datum(d.gewuenscht)} → ${datum(d.bestaetigt)}` : null],
  ].filter(([, wert]) => wert !== null);
  return `<dl class="gitter">${felder.map(([name, wert]) => `<div><dt>${name}</dt><dd>${wert}</dd></div>`).join('')}</dl>`;
};

const ARTEN = {
  liefertermin_pruefen: 'Liefertermin prüfen', preis_freigeben: 'Preis freigeben', preiserhoehung_pruefen: 'Preiserhöhung prüfen',
  preis_info: 'Info: Preisänderung', ab_klaeren: 'Auftragsbestätigung klären', bearbeiten: 'Bearbeiten', eskalation: 'Preiserhöhung freigeben',
  technik_freigabe: 'Technik-Freigabe', qm_freigabe: 'QM-Freigabe', bestand_pruefen: 'Bestand und letzte Bestellung prüfen',
  entwurf_senden: 'Entwurf prüfen und senden',
};
// Status-Badge: kritisch bei Eskalation oder über 10 %, Warnung bei hoher Priorität, sonst neutral; Infos grün
const status = (a) => {
  const p = a.details?.prozent;
  if (a.art === 'eskalation') return badge('krit', a.team === 'Geschäftsleitung' ? 'Eskalation GL' : 'Eskalation', true);
  if (['technik_freigabe', 'qm_freigabe'].includes(a.art)) return badge('krit', 'Freigabe nötig', true);
  if (a.art === 'entwurf_senden') return badge('neutral', a.details?.art === 'intern' ? 'Entwurf intern' : 'Entwurf Lieferant');
  if (p != null && p > Number(e.preis_eskalation_strategie_prozent ?? 10) && a.status === 'offen') return badge('krit', `> ${pz(e.preis_eskalation_strategie_prozent ?? 10)}`, true);
  if (a.status === 'info') return badge('ok', a.art === 'preis_info' && a.team === 'Einkauf' ? 'Auto-Freigabe' : 'Info');
  if (a.prioritaet === 'hoch') return badge('warn', 'Hohe Priorität');
  if (a.art === 'preis_freigeben') return badge('ok', 'Freigabe Dispo');
  return badge('neutral', 'Offen');
};

// Entscheiden direkt in der Karte. Jede Aktion ist ein POST an /webhook/aufgabe (kein Link: Link-Vorschauen und
// Prefetching dürfen nichts freigeben). Der Server prüft Herkunft, Aktion und Name und schreibt ins Audit-Protokoll.
// Im Screenshot-Modus gibt es keine Aktionen.
const PREISARTEN = ['preis_freigeben', 'preiserhoehung_pruefen', 'eskalation'];
const ENTSCHEIDBAR = [...PREISARTEN, 'technik_freigabe', 'qm_freigabe'];
// Preisfreigabe gesperrt, solange Technik und QM nicht beide freigegeben haben: wenn sie eingebunden sind
// oder wenn Modell bzw. Regel sie für nötig halten (dann müssen sie erst eingebunden werden)
const gesperrt = (a) => {
  const auf = a.ticket_aufgaben ?? [];
  const frei = (art) => auf.some((y) => y.art === art && y.entscheidung === 'freigegeben');
  const noetig = a.abteilungen?.technik || a.abteilungen?.qm || auf.some((y) => ['technik_freigabe', 'qm_freigabe'].includes(y.art));
  return Boolean(noetig) && !(frei('technik_freigabe') && frei('qm_freigabe'));
};
const formular = (felder, inhalt, bestaetigen = '') => `<form method="post" action="/webhook/aufgabe" class="entscheiden"${bestaetigen ? ` data-bestaetigen="${esc(bestaetigen)}"` : ''}>
  ${Object.entries(felder).map(([name, wert]) => `<input type="hidden" name="${name}" value="${esc(wert)}">`).join('')}<input type="hidden" name="akteur" value="">${inhalt}</form>`;
const aktionsleiste = (a) => {
  if (anonym || a.status !== 'offen') return '';
  const sperre = PREISARTEN.includes(a.art) && gesperrt(a);
  const knoepfe = ENTSCHEIDBAR.includes(a.art)
    ? (sperre ? `<button class="knopf klein" type="button" disabled title="Erst nach Freigabe durch Technik und QM">${ICON.schloss}Freigeben</button>`
      : formular({ id: a.id, aktion: 'freigegeben' }, `<button class="knopf klein gruen" type="submit">${ICON.haken}Freigeben</button>`))
      + formular({ id: a.id, aktion: 'abgelehnt' }, '<button class="knopf klein rot" type="submit">Ablehnen</button>')
    : formular({ id: a.id, aktion: 'erledigt' }, `<button class="knopf klein gruen" type="submit">${ICON.haken}${a.art === 'entwurf_senden' ? 'Als gesendet markieren' : 'Erledigt'}</button>`);
  // Abteilungen einbinden und Unterlagen anfordern, solange das im Vorgang noch nicht passiert ist
  const ab = a.abteilungen ?? {};
  const hinweis = (ab.technik || ab.qm || ab.dispo) && !['technik_freigabe', 'qm_freigabe', 'bestand_pruefen', 'entwurf_senden'].includes(a.art);
  const einbinden = hinweis && !(a.ticket_aufgaben ?? []).some((y) => y.art === 'technik_freigabe')
    ? formular({ id: a.id, aktion: 'einbinden' }, `<button class="knopf klein" type="submit">Technik &amp; QM einbinden</button>`) : '';
  const unterlagen = hinweis && !(a.entwurf_zwecke ?? []).includes('unterlagen_anfordern')
    ? formular({ id: a.id, aktion: 'unterlagen' }, '<button class="knopf klein" type="submit">Erstmuster/Zeugnis anfordern</button>') : '';
  const vorlage = a.team === 'Einkauf' && a.bestellnummer && a.art !== 'entwurf_senden' ? '<a class="knopf klein" href="/form/entwurf">Vorlage</a>' : '';
  const mail = a.mailtext ? `<details class="mail"><summary class="knopf klein">Mail anzeigen</summary><pre>${esc(a.mailtext)}</pre></details>` : '';
  return `<footer class="aktionsleiste">${knoepfe}${einbinden}${unterlagen}${vorlage}${mail}</footer>`;
};

// Sortierwerte für die Filterleiste. Im Screenshot-Modus nur der Rang, damit der Betrag nicht im Quelltext steht.
const jahresWerte = [...new Set(aufgaben.map((a) => Number(a.details?.jahres_mehrkosten_eur ?? 0)))].sort((x, y) => x - y);
const sortJahr = (a) => { const w = Number(a.details?.jahres_mehrkosten_eur ?? 0); return anonym ? jahresWerte.indexOf(w) : w; };
const sortPrio = (a) => (a.art === 'eskalation' ? 3 : a.prioritaet === 'hoch' ? 2 : a.status === 'offen' ? 1 : 0);

const karte = (a) => {
  const liste = befunde(a);
  const ohneDaten = (!a.details || !Object.keys(a.details).length) && a.art !== 'entwurf_senden';
  return `
  <article class="karte${a.art === 'eskalation' ? ' kritisch' : ''}" data-id="${esc(a.id)}" data-jahr="${sortJahr(a)}" data-prio="${sortPrio(a)}">
    <header>
      <div class="kopfzeile"><h3>${lieferant(a.lieferant)}</h3><div class="meta num">#${esc(a.ticket_id)} · ${esc(a.erstellt)}</div></div>
      <div class="titel">${status(a)}<span class="art">${esc(ARTEN[a.art] ?? a.art)}</span></div>
    </header>
    ${gitter(a)}
    ${liste.length ? `<ul class="befunde">${liste.join('')}</ul>` : ''}
    ${ohneDaten && (a.zusammenfassung || a.betreff) ? `<p class="text">${anonym ? AUSGEBLENDET : esc(a.zusammenfassung ?? a.betreff)}</p>` : ''}
    ${a.art === 'entwurf_senden' && a.ew_text ? (anonym ? `<p class="text">${AUSGEBLENDET}</p>` : `<div class="entwurf">
      <div class="leise">An: <span class="num">${esc(a.ew_empfaenger)}</span>${a.ew_cc ? ` · Cc: <span class="num">${esc(a.ew_cc)}</span>` : ''}</div>
      ${(a.ew_warnungen ?? []).length ? `<p class="hinweis">${ICON.warnung} Bitte prüfen: ${a.ew_warnungen.map(esc).join(', ')}</p>` : ''}
      <pre><b>${esc(a.ew_betreff)}</b>\n\n${esc(a.ew_text)}</pre></div>`) : ''}
    ${!anonym && a.art !== 'entwurf_senden' && a.entwurf_text && a.team === 'Einkauf' && a.status === 'offen' ? `<details><summary>Antwortentwurf <span class="leise">${esc(a.foermlichkeit)}, ${esc(a.nachdruck)}</span></summary>
      ${(a.entwurf_warnungen ?? []).length ? `<p class="hinweis">${ICON.warnung} Bitte prüfen: ${a.entwurf_warnungen.map(esc).join(', ')}</p>` : ''}
      <pre><b>${esc(a.entwurf_betreff)}</b>\n\n${esc(a.entwurf_text)}</pre></details>` : ''}
    ${aktionsleiste(a)}
  </article>`;
};

// Kennzahlen oben: offene Eskalationen, offene Reviews, Automatisierungsquote, Jahreswirkung offener Preiserhöhungen
const offen = aufgaben.filter((a) => a.status === 'offen');
const infos = aufgaben.filter((a) => a.status === 'info');
const eskalationen = offen.filter((a) => a.art === 'eskalation').length;
const quote = Number(k.gesamt_30) ? Math.round((Number(k.automatisch_30) / Number(k.gesamt_30)) * 100) : null;
// Jahreswirkung je Ticket nur einmal zählen (Einkäufer und Eskalation tragen dieselben Details)
const jahresJeTicket = new Map();
for (const a of offen) if (a.details?.jahres_mehrkosten_eur != null) jahresJeTicket.set(a.ticket_id, Number(a.details.jahres_mehrkosten_eur));
const jahresSumme = [...jahresJeTicket.values()].reduce((s, x) => s + x, 0);
const kpi = (titel, wert, unter, ton = '') => `<div class="kpi ${ton}"><div class="kpi-titel">${titel}</div><div class="kpi-wert num">${wert}</div><div class="kpi-unter">${unter}</div></div>`;
const kennzahlen = `<section class="kpis">
  ${kpi('Offene Eskalationen', eskalationen, 'Einkaufsleitung und Geschäftsleitung', eskalationen ? 'krit' : '')}
  ${kpi('Offene Reviews', reviews.length, 'Entscheidung durch einen Menschen', reviews.length ? 'warn' : '')}
  ${kpi('Auto-Quote 30 Tage', quote === null ? '–' : `${quote}&nbsp;%`, `<span class="num">${esc(k.automatisch_30)}</span> von <span class="num">${esc(k.gesamt_30)}</span> Mails ohne Review`)}
  ${kpi('Jahreswirkung offen', anonym ? '***.*** €' : `${Math.round(jahresSumme).toLocaleString('de-DE')}&nbsp;€`, `aus <span class="num">${jahresJeTicket.size}</span> offenen Preisänderungen`)}
</section>`;

const REIHENFOLGE = ['Geschäftsleitung', 'Einkaufsleitung', 'Technik', 'Qualitätsmanagement', 'Einkauf', 'Disposition', 'Strategischer Einkauf'];
const teams = [...new Set(offen.map((a) => a.team))]
  .sort((x, y) => ((REIHENFOLGE.indexOf(x) + 1 || 99) - (REIHENFOLGE.indexOf(y) + 1 || 99)) || x.localeCompare(y));
const teamBereiche = teams.map((team) => {
  const eigene = offen.filter((a) => a.team === team);
  return `<section class="bereich" data-team="${esc(team)}"><h2>${esc(team)}<span class="zaehler num">${eigene.length}</span></h2><div class="raster" data-sortierbar>${eigene.map(karte).join('')}</div></section>`;
}).join('');

// Filterleiste: ein Reiter je Team mit offenen Aufgaben, dazu die Sortierung. Gefiltert und sortiert wird im Browser,
// die Daten sind schon auf der Seite. "Alle" zeigt zusätzlich Review-Queue, Infos und Audit-Protokoll.
const filterleiste = `<div class="filter" role="tablist">
  <button type="button" role="tab" class="reiter" data-filter="alle" aria-selected="true">Alle<span class="num">${offen.length}</span></button>
  ${teams.map((t) => `<button type="button" role="tab" class="reiter" data-filter="${esc(t)}" aria-selected="false">${esc(t)}<span class="num">${offen.filter((a) => a.team === t).length}</span></button>`).join('')}
  <label class="sortierung">Sortieren nach
    <select id="sortierung"><option value="jahr">Full-Year-Effekt (absteigend)</option><option value="prio">Priorität</option><option value="neu">Neueste zuerst</option></select>
  </label>
</div>`;

// Sammelfreigabe: nur Preisfreigaben in der Kompetenz der Disposition ohne Warnhinweis. Welche das sind, entscheidet
// beim Absenden der Server mit denselben Kriterien. Die Seite zeigt nur Anzahl und Summe für die Rückfrage.
const unkritisch = offen.filter((a) => a.art === 'preis_freigeben' && a.details?.angabe_lieferant_prozent == null && !gesperrt(a)
  && Number(a.details?.prozent_12_monate ?? 0) <= Number(e.preis_toleranz_dispo_prozent ?? 5));
const unkritischSumme = unkritisch.reduce((s, a) => s + Number(a.details?.mehrkosten_eur ?? a.details?.mehrkosten ?? 0), 0);
const sammelknopf = anonym ? '' : unkritisch.length
  ? formular({ sammel: '1' }, `<button class="knopf gruen" type="submit">${ICON.haken}Unkritische ABs freigeben<span class="num">${unkritisch.length}</span></button>`,
      `${unkritisch.length} Preisfreigaben innerhalb der Kompetenz der Disposition freigeben (Mehrkosten zusammen ${de(unkritischSumme)} €)? Jede Freigabe wird mit deinem Namen protokolliert.`)
  : '<button class="knopf" type="button" disabled>Keine unkritischen ABs</button>';

// Review-Queue: Betrug und Manipulation kritisch, alles andere als Warnung
const KRITISCH = ['bankdatenaenderung', 'prompt_injection_verdacht', 'lieferant_unbekannt'];
const GRUND = {
  bankdatenaenderung: 'Bankdaten geändert', prompt_injection_verdacht: 'Prompt-Injection', kategorie_unplausibel: 'Kategorie unplausibel',
  konfidenz_niedrig: 'Konfidenz niedrig', bestellung_unbekannt: 'Bestellung unbekannt', lieferant_unbekannt: 'Lieferant unbekannt',
  llm_fehler: 'LLM nicht erreichbar', json_ungueltig: 'Ausgabe ungültig', schema_verletzt: 'Schema verletzt',
};
const REGEL = {
  bankdatenaenderung: 'Regel: Mails mit geänderter Bankverbindung gehen immer an einen Menschen, unabhängig von der Konfidenz',
  prompt_injection_verdacht: 'Regel: Text enthält typische Anweisungen an das Modell',
  kategorie_unplausibel: 'Regel: Angebot oder Preiserhöhung mit unserer Bestellnummer (45 + 8 Ziffern) ist vermutlich eine AB',
  konfidenz_niedrig: `Regel: Konfidenz des Modells unter der Schwelle`,
  bestellung_unbekannt: 'Regel: Bestellnummer nicht in den offenen Bestellungen (z. B. Zahlendreher)',
  lieferant_unbekannt: 'Regel: Absender-Domain gehört zu keinem Lieferanten',
};
const reviewZeilen = reviews.map((r) => `<tr>
    <td class="num">#${esc(r.id)}</td>
    <td>${r.gruende.map((g) => `${badge(KRITISCH.includes(g) ? 'krit' : 'warn', GRUND[g] ?? g.replace(/_/g, ' '), KRITISCH.includes(g))}${regel(REGEL[g])}`).join(' ')}</td>
    <td>${anonym ? AUSGEBLENDET : esc(r.betreff)}<div class="leise">${anonym ? '' : esc(r.absender)}</div></td>
    <td><span class="num">${esc(r.vorschlag ?? '–')}</span><div class="leise num">Konfidenz ${esc(r.konfidenz ?? '–')}</div></td>
    <td class="num leise">${esc(r.erstellt)}</td>
  </tr>`).join('');

// Audit-Protokoll: nur anhängbar, mit Prüfung der Hash-Kette
const AKTIONEN = { review_freigegeben: 'Review freigegeben', review_verworfen: 'Review verworfen', aufgabe_freigegeben: 'Aufgabe freigegeben',
  aufgabe_abgelehnt: 'Aufgabe abgelehnt', aufgabe_erledigt: 'Aufgabe erledigt', sammelfreigabe: 'Sammelfreigabe',
  aufgabe_einbinden: 'Technik & QM eingebunden', aufgabe_unterlagen: 'Unterlagen angefordert' };
const kette = Number(k.anzahl) === 0 ? badge('neutral', 'Noch keine Einträge')
  : k.defekte_zeile ? badge('krit', `Kette ab Eintrag ${k.defekte_zeile} verändert`, true) : badge('ok', 'Hash-Kette intakt');
const auditZeilen = (k.eintraege ?? []).map((z) => `<tr>
