  <td>${esc(AKTIONEN[z.aktion] ?? z.aktion)} <span class="num">#${esc(z.objekt_id)}</span>${z.details?.kategorie ? ` → <span class="num">${esc(z.details.kategorie)}</span>` : ''}${z.details?.vorschlag_llm ? ` <span class="leise">LLM: ${esc(z.details.vorschlag_llm)}</span>` : ''}${z.details?.art ? ` <span class="leise">${esc(ARTEN[z.details.art] ?? z.details.art)}, ${esc(z.details.team)}</span>` : ''}</td>
  <td>${anonym ? (z.details?.notiz ? AUSGEBLENDET : '') : esc(z.details?.notiz ?? '')}</td><td class="num leise">${esc(z.hash)}</td></tr>`).join('');

